function k08ApplyEffect(answerPk) {
    const fx = K08_EFFECTS[Number(answerPk)];
    if (!fx) return;
    Object.keys(fx).forEach(key => {
        campaignTrail_temp.k08[key] = Number(campaignTrail_temp.k08[key] || 0) + Number(fx[key] || 0);
    });
    const trustDelta = Number(fx.progressiveTrust || 0);
    const bonus = Number(K08_PURITY_BONUS[Number(answerPk)] || 0);
    campaignTrail_temp.k08.kucinichPurity = Math.max(0, Number(campaignTrail_temp.k08.kucinichPurity || 0) + trustDelta + bonus);
}

