function k08EnsureCenterTicketBanner() {
    const vpId = Number(campaignTrail_temp?.selected_running_mate_id || 0);
    const vpMap = {31:"gravel",32:"lee",33:"paul",34:"patrick",35:"napolitano",36:"feingold"};
    const actuallyChosen = campaignTrail_temp?.k08?.vpChosen === true && !!vpMap[vpId];
    const key = actuallyChosen ? vpMap[vpId] : "before";
    const url = K08_BANNERS[key] || K08_BANNERS.before;

    const textNodes = Array.from(document.querySelectorAll("div,span,h1,h2,h3,h4,p"));
    let label = textNodes.find(el => {
        if (el.id === "k08_center_ticket_banner_wrap") return false;
        const text = String(el.textContent || "").replace(/\s+/g," ").trim().toLowerCase();
        return text === "kucinich party" || text === "kucinich democratic party";
    });

    let wrap = document.getElementById("k08_center_ticket_banner_wrap");
    if (!wrap && label) {
        let target = label;
        while (target.parentElement && target.parentElement.textContent.trim() === label.textContent.trim() && target.parentElement.children.length <= 2) {
            target = target.parentElement;
        }
        wrap = document.createElement("div");
        wrap.id = "k08_center_ticket_banner_wrap";
        wrap.style.cssText = "display:flex;align-items:center;justify-content:center;width:100%;min-height:92px;overflow:hidden;background:transparent;padding:2px 8px;box-sizing:border-box;";
        const img = document.createElement("img");
        img.id = "k08_center_ticket_banner";
        img.alt = "Kucinich campaign ticket banner";
        img.style.cssText = "display:block;width:auto;max-width:96%;height:auto;max-height:88px;object-fit:contain;margin:4px auto 0 auto;";
        wrap.appendChild(img);
        target.replaceWith(wrap);
    }

    if (wrap) {
        let banner = document.getElementById("k08_center_ticket_banner");
        if (!banner) {
            banner = document.createElement("img");
            banner.id = "k08_center_ticket_banner";
            banner.alt = "Kucinich campaign ticket banner";
            banner.style.cssText = "display:block;width:auto;max-width:96%;height:auto;max-height:88px;object-fit:contain;margin:4px auto 0 auto;";
            wrap.replaceChildren(banner);
        }
        banner.src = url;
    }
}

