function k08GetVpRecords() {
    const k = campaignTrail_temp.k08 || {};
    const feingoldUnlocked = !k.denverRiot && Number(k.progressiveTrust||0) >= 10 && Number(k.partySupport||0) >= 5;
    k.feingoldUnlocked = feingoldUnlocked;
    const ids = k.denverRiot ? [31,32,33] : (feingoldUnlocked ? [31,32,33,34,35,36] : [31,32,33,34,35]);
    return ids.map(id => {
        let rec = campaignTrail_temp.candidate_json?.find(c => Number(c.pk) === id);
        const f = K08_VP_FALLBACKS[id];
        if (rec?.fields && f) {
            if (!rec.fields.description_as_running_mate) rec.fields.description_as_running_mate = f.description_as_running_mate;
            if (!rec.fields.candidate_score) rec.fields.candidate_score = f.candidate_score;
        }
        if (rec?.fields && K08_VP_QUESTION_PORTRAITS[id]) rec.fields.image_url = K08_VP_QUESTION_PORTRAITS[id];
        if (!rec) {
            rec = {model:"campaign_trail.candidate",pk:id,fields:{...f,election:3,priority:id-27,color_hex:"#0000FF",secondary_color_hex:"#90C0FF",is_active:0,description:"",electoral_victory_message:"n/a",electoral_loss_message:"n/a",no_electoral_majority_message:"n/a",running_mate:true}};
            campaignTrail_temp.candidate_json = campaignTrail_temp.candidate_json || [];
            campaignTrail_temp.candidate_json.push(rec);
        }
        return rec;
    });
}

function k08GameHost() {
    return document.getElementById("game_window") || document.querySelector(".game_window") || document.body;
}

function k08HideGame(hide) {
    const host = k08GameHost();
    const display = hide ? "none" : "";
    Array.from(host.children).forEach(child => {
        if (child.id !== "k08_vp_screen" && !child.classList.contains("game_header")) child.style.display = display;
    });
}

campaignTrail_temp.k08VpSwitcher = function() {
    if (document.getElementById("k08_vp_screen") || campaignTrail_temp.k08.vpChosen) return;
    const records = k08GetVpRecords();
    const first = records[0];
    let selectedPk = Number(first.pk);
    const screen = document.createElement("div");
    screen.id = "k08_vp_screen";
    screen.className = "inner_window_w_desc";
    screen.style.cssText = "display:block;position:relative;z-index:1000;padding:14px;max-height:78vh;overflow-y:auto;";
    const buttons = records.map(c => `<button type="button" class="k08-vp-choice btn" data-pk="${c.pk}" style="margin:3px;padding:7px 10px;">${c.fields.first_name} ${c.fields.last_name}</button>`).join("");
    screen.innerHTML = `
      <div class="person_description_window" style="padding:14px;">
        <h3>Please select your running mate:</h3>
        <div id="k08_vp_buttons" style="display:flex;flex-wrap:wrap;gap:5px;margin:8px 0 14px 0;">${buttons}</div>
        <div style="display:flex;gap:16px;align-items:flex-start;">
          <img id="k08_vp_img" src="${first.fields.image_url}" style="width:150px;max-width:35%;height:auto;object-fit:cover;">
          <div id="k08_vp_desc" style="flex:1;"></div>
        </div>
        <button id="k08_vp_continue" class="btn btn-primary" style="margin-top:14px;">Continue</button>
      </div>`;
    k08HideGame(true);
    k08GameHost().appendChild(screen);
    const render = () => {
        const c = records.find(x => Number(x.pk) === selectedPk) || first;
        screen.querySelector("#k08_vp_img").src = c.fields.image_url;
        screen.querySelector("#k08_vp_desc").innerHTML =
          `<b>Name:</b> ${c.fields.first_name} ${c.fields.last_name}<br>` +
          `<b>Party:</b> ${c.fields.party}<br>` +
          `<b>Home State:</b> ${c.fields.state}<br><br>` +
          (c.fields.description_as_running_mate || "");
        screen.querySelectorAll(".k08-vp-choice").forEach(b => {
            b.style.fontWeight = Number(b.dataset.pk) === selectedPk ? "bold" : "normal";
            b.style.outline = Number(b.dataset.pk) === selectedPk ? "2px solid currentColor" : "none";
        });
    };
    screen.querySelectorAll(".k08-vp-choice").forEach(btn => btn.addEventListener("click", () => {selectedPk=Number(btn.dataset.pk);render();}));
    render();
    screen.querySelector("#k08_vp_continue").addEventListener("click", ev => {
        ev.preventDefault();
        const chosen = records.find(x => Number(x.pk) === selectedPk) || first;
        const shell = campaignTrail_temp.candidate_json?.find(c => Number(c.pk) === 30);
        if (shell) {
            ["first_name","last_name","state","image_url","description_as_running_mate","candidate_score","party"].forEach(k => shell.fields[k] = chosen.fields[k]);
        }
        campaignTrail_temp.running_mate_first_name = chosen.fields.first_name;
        campaignTrail_temp.running_mate_last_name = chosen.fields.last_name;
        campaignTrail_temp.running_mate_image_url = chosen.fields.image_url;
        campaignTrail_temp.selected_running_mate_id = Number(chosen.pk);
        campaignTrail_temp.k08.democraticVp = K08_VP_KEYS[Number(chosen.pk)] || "gravel";
        k08InstallVpFollowup(campaignTrail_temp.k08.democraticVp);
        k08SetCampaignBanner(campaignTrail_temp.k08.democraticVp);
        campaignTrail_temp.k08.vpChosen = true;
        campaignTrail_temp.k08.vpSelectionPending = false;
        if(campaignTrail_temp.k08._vpGateTimer){
          clearInterval(campaignTrail_temp.k08._vpGateTimer);
          campaignTrail_temp.k08._vpGateTimer=null;
        }
        screen.remove();
        k08HideGame(false);
        if (typeof questionHTML === "function") questionHTML();
    });
};

const K08_VP_FOLLOWUPS = {
  gravel: {
    q: "Mike Gravel has joined the ticket, and the press is already calling it the angriest and least conventional Democratic ticket in modern history. How should the two of you introduce the partnership?",
    a: [
      "Let's lean into it. Mike and I were both right about Iraq, both ignored when it was convenient, and neither of us owes the political establishment an apology for being here.",
      "I want Mike out there as the elder statesman on war and constitutional questions. I'll spend more of my time making the case on health care, jobs, and the economy.",
      "Mike's outsider streak is part of why I picked him, and I want people to see the humor in that. But I also want us speaking with one voice on policy and not spending March picking fights with every Democrat in Washington.",
      "I don't want to turn this into a buddy act. This is a coalition of movements and ideas, not two men auditioning for television."
    ]
  },
  lee: {
    q: "Barbara Lee's selection has electrified anti-war activists and many former Obama supporters, but Republicans are calling the ticket dangerously far left. How do you introduce her?",
    a: [
      "Barbara cast the vote almost nobody else was willing to cast after September 11th. I think that kind of judgment and courage is exactly what a vice president ought to bring to the room.",
      "I want people to know Barbara as more than one famous vote. She's a serious legislator who's spent her career fighting for people Washington finds easy to ignore.",
      "There's no replacing Barack Obama, and I'm not going to pretend there is. But I do want Barbara beside me making the case that the people inspired by his campaign still have a home in this one.",
      "Let's make this simple: Barbara is going to be a governing partner, not a protest symbol. We can be bold and still show the country we're prepared to run an administration."
    ]
  },
  paul: {
    q: "Choosing Ron Paul has stunned both parties. Supporters see a genuine anti-war realignment; critics see two ideological outsiders with incompatible views on nearly everything else. What is the case for this ticket?",
    a: [
      "The war state, the Patriot Act, and too much concentrated power have survived because both parties learned to live with them. Ron and I are here to break that arrangement.",
      "I'm not asking anybody to pretend Ron and I agree on everything. We agree on peace, civil liberties, constitutional government, and the need for an honest argument where we don't.",
      "Ron proves that opposition to endless war isn't confined to the Democratic left. On domestic policy, I'm still running on my platform and I'm not going to blur that distinction.",
      "I actually think the disagreements help make the point. A coalition doesn't require everybody to surrender his principles; it requires people to know what they're joining together to accomplish."
    ]
  },
  patrick: {
    q: "Deval Patrick gives the ticket a younger, more optimistic face and an immediate connection to many grieving Obama supporters. Some activists, however, worry that he was chosen mainly for symbolism. How do you introduce him?",
    a: [
      "Deval understands why so many people responded to a politics of hope. I want to pair that hope with the structural changes this campaign has been fighting for from the beginning.",
      "I picked Deval because he's governed. He knows how to turn progressive principles into an administration that actually has to make decisions and deliver results.",
      "I want Deval talking directly to people who supported Barack, especially Black voters who have every reason to be grieving and skeptical. But nobody on this ticket is going to pretend one man can replace another.",
      "People think they know what a Kucinich campaign sounds like. Deval helps me show them that we can be bold while keeping our policy grounded."
    ]
  },
  feingold: {
    q: "Russ Feingold has proven to be a popular choice so far, and even some skeptical Democrats seem relieved by the selection. Still, a few commentators are asking what exactly he adds to the ticket. Their argument is that picking another anti-war Midwestern liberal looks less like expanding your coalition and more like doubling down on the strategy that got you here. What do you say?",
    a: [
      "Russ is perfect for the job. It's really that simple. I don't see why the state he comes from is even relevant to anyone outside of the political consultant class.",
      "Look at what Russ has accomplished with campaign finance reform. He's exactly the kind of person we need, someone who sees the current system for what it is: legalized bribery.",
      "Let's not forget, Russ will make history as the first Jewish Vice President. He shows that people of all backgrounds support our message and want to get the country back on track."
    ]
  },
  napolitano: {
    q: "Janet Napolitano is being praised as a conventional, governing-minded choice, though some progressives call her a retreat from the insurgency that won the nomination. How do you introduce her?",
    a: [
      "Janet has governed a border state. She knows from experience that practical administration and progressive values are not opposites, and that's exactly why I wanted her on this ticket.",
      "I want Janet talking about homeland security and executive competence. Voters should be able to look at this ticket and know we're prepared to govern on the first day.",
      "Janet can reassure people who are nervous about me without changing what I ran on. I didn't pick a running mate so I could quietly throw the platform overboard.",
      "This choice makes the campaign bigger. An Ohio-Arizona ticket gives us a real chance to compete in places Democrats too often decide are somebody else's territory."
    ]
  }
};

function k08InstallVpFollowup(key) {
    const row = K08_VP_FOLLOWUPS[key] || K08_VP_FOLLOWUPS.gravel;
    const q = campaignTrail_temp.questions_json?.find(x => Number(x.pk) === 33);
    if (q?.fields) q.fields.description = row.q;
    const vpIntroScores = {
      napolitano:[0.003,0.005,0.004,-0.003],
      feingold:[0.0025,0.0025,-0.003,0],
      patrick:[0.002,0.004,0.003,-0.004],
      lee:[-0.006,0.001,-0.001,-0.008],
      gravel:[-0.010,-0.003,-0.005,-0.012],
      paul:[-0.018,-0.009,-0.011,-0.022]
    }[key] || [-0.008,-0.002,-0.004,-0.010];
    [126,127,128,129].forEach((pk,i) => {
        const a = campaignTrail_temp.answers_json?.find(x => Number(x.pk) === pk);
        if (a?.fields) {
          if(key==="feingold" && i===3) a.fields.question=9999;
          else { a.fields.question=33; a.fields.description=row.a[i]; }
        }
        const g=k08EnsureGlobalRecord(pk,vpIntroScores[i]);
        if(g?.fields) g.fields.global_multiplier=vpIntroScores[i];
    });
    if(key==="feingold"){
      const feedback=[
        "Fair enough. Most voters seem to like Feingold, and nobody outside a Sunday morning panel is spending much time worrying about whether Ohio borders Wisconsin. It doesn't change many minds, but the confidence plays well.",
        "McCain-Feingold gives the argument some substance, and Russ is pretty good evidence that you can hate the way Washington works without being completely incapable of working in Washington.",
        "We probably could've handled that one better. Feingold's nomination is historic, but after plenty of Democrats spent months hoping you'd choose a woman or a Black running mate, congratulating ourselves on the diversity of the ticket lands a little strangely. People still like Russ; this just isn't the reason they needed to hear."
      ];
      [126,127,128].forEach((pk,i)=>{
        const a=campaignTrail_temp.answers_json?.find(x=>Number(x.pk)===pk);
        if(a?.fields)a.fields.feedback=feedback[i];
        if(typeof k08SetFeedback==="function")k08SetFeedback(pk,feedback[i]);
      });
    }
}

