function k08OppositionHtml() {
    const unlocked = Boolean(campaignTrail_temp?.k08?.oppositionUnlocked || (campaignTrail_temp?.k08?.republicanNominee && campaignTrail_temp?.k08?.republicanVp));
    if (!unlocked) {
      return `<div id="k08_opposition_panel" style="padding:12px 14px;max-width:360px;margin:auto;">
        <h2 style="text-align:center;margin:0 0 10px;">The Opposition</h2>
        <img src="https://i.imgur.com/uC4Y7Nn.png" style="display:block;max-width:285px;width:84%;max-height:185px;object-fit:contain;margin:4px auto 8px;" alt="">
        <h3 style="text-align:center;font-size:17px;margin:7px 0 5px;">No Republican Ticket Yet</h3>
        <p style="text-align:center;font-weight:700;font-style:italic;margin:5px auto 0;max-width:315px;">${K08_OPPOSITION_PLACEHOLDER.summary}</p>
      </div>`;
    }
    const key = k08TicketKey();
    const asset = K08_OPPOSITION_ASSETS[key] || {};
    const nom = K08_GOP[campaignTrail_temp.k08.republicanNominee];
    const hh = String(campaignTrail_temp.k08.republicanNominee||"").toLowerCase()==="huckabee" && String(campaignTrail_temp.k08.republicanVp||"").toLowerCase()==="hagee";
    const vp = hh ? {first_name:"John",last_name:"Hagee"} : k08Record(K08_GOP_VP_RECORDS[campaignTrail_temp.k08.republicanVp])?.fields;
    const logo = asset.logo ? `<img src="${asset.logo}" style="display:block;max-width:285px;width:84%;max-height:220px;object-fit:contain;margin:0 auto 8px;">` : "";
    const photo = asset.photo ? `<img src="${asset.photo}" style="display:block;max-width:285px;width:84%;max-height:220px;object-fit:contain;margin:0 auto 8px;">` : "";
    return `<div id="k08_opposition_panel" style="padding:10px 14px;max-width:370px;margin:auto;">
      <h2 style="text-align:center;margin:0 0 8px;">The Opposition</h2>${logo}${photo}
      <h3 style="text-align:center;font-size:17px;margin:7px 0 5px;">${nom?.first || "Republican"} ${nom?.last || "Nominee"} / ${vp?.first_name || ""} ${vp?.last_name || ""}</h3>
      <p style="text-align:center;font-weight:700;font-style:italic;margin:5px auto 0;max-width:320px;">${asset.summary || k08TicketNarrative(campaignTrail_temp.k08.republicanNominee,campaignTrail_temp.k08.republicanVp)}</p>
    </div>`;
}

function k08OpenOppositionPanel() {
  document.getElementById("k08_opposition_overlay")?.remove();
  const overlay=document.createElement("div");
  overlay.id="k08_opposition_overlay";
  overlay.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,.58);z-index:99999;display:flex;align-items:center;justify-content:center;padding:18px;";
  overlay.innerHTML=`<div style="position:relative;background:#fff;color:#111;border:3px solid #555;max-width:410px;width:min(410px,94vw);max-height:88vh;overflow:auto;box-shadow:0 5px 22px rgba(0,0,0,.55);">
    <button type="button" id="k08_opposition_close" aria-label="Close" style="position:absolute;right:7px;top:5px;border:1px solid #777;background:#eee;font-size:18px;line-height:1;padding:3px 7px;cursor:pointer;z-index:2;">×</button>
    ${k08OppositionHtml()}
  </div>`;
  document.body.appendChild(overlay);
  const close=()=>overlay.remove();
  overlay.querySelector("#k08_opposition_close")?.addEventListener("click",close);
  overlay.addEventListener("click",e=>{if(e.target===overlay) close();});
}

function k08InstallOppositionTab() {
  const install=()=>{
    const buttons=[...document.querySelectorAll("button,a,.btn,[role='button']")];
    const poll=buttons.find(el=>/latest polls|electoral map/i.test((el.textContent||"").trim()));
    if (!poll || document.getElementById("k08_opposition_button")) return;
    const btn=document.createElement(poll.tagName.toLowerCase()==="a" ? "a" : "button");
    btn.id="k08_opposition_button";
    btn.type="button";
    btn.className=poll.className;
    btn.textContent="The Opposition";
    btn.style.marginLeft="8px";
    btn.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();k08OpenOppositionPanel();});
    poll.insertAdjacentElement("afterend",btn);
  };
  campaignTrail_temp.k08RefreshOppositionTab=install;
  install();
  const oppositionInstallObserver=new MutationObserver(()=>{
    install();
    if(document.getElementById("k08_opposition_button")) oppositionInstallObserver.disconnect();
  });
  if(!document.getElementById("k08_opposition_button")){
    oppositionInstallObserver.observe(document.body,{childList:true,subtree:true});
  }
}
window.setTimeout(k08InstallOppositionTab,250);

const K08_BRANCH_COPY = {"romney-manchin":[{"qpk":1001,"apk":2001,"q":"Some days later, Mitt Romney announced West Virginia Governor Joe Manchin as his running mate. Republicans are selling the ticket as managerial competence joined to working-class moderation. It is a clever answer to our image problem, but not necessarily an unbeatable one. Where do we start?","a":["Welcome Manchin's presence and argue that even this ticket cannot disguise Romney's economic program.","Make Romney's private-sector record the center of the race before he defines it as competence.","Attack Manchin as a Democrat who abandoned his party when it became inconvenient.","Ignore the personalities and lay out a detailed economic program of our own."]},{"qpk":1002,"apk":2005,"q":"Romney keeps returning to competence, budgets, and his career in business. The debate moderator asks why voters should trust a congressman who has never run a state over a successful executive. What is the answer?","a":["Go directly at Bain Capital and ask what 'success' meant for workers whose jobs disappeared.","Say Washington experience matters too; after more than a decade in the House, I know exactly how this place fails.","Call Romney hopelessly out of touch with ordinary people and leave it there.","Refuse the résumé contest and make the debate about whose economic judgment fits this moment."]},{"qpk":1003,"apk":2009,"q":"Manchin plans to portray your running mate as proof that the Democratic ticket has left normal voters behind. How should the vice-presidential debate handle him?","a":["Treat Manchin respectfully, then force him to explain which Romney policies a conservative Democrat is actually endorsing.","Attack him as an opportunist who crossed party lines for ambition.","Let our running mate make an unapologetic ideological case and dare Manchin to answer it.","Keep the focus on Romney's business record and deny Manchin the chance to become the reassuring face of the ticket."]},{"qpk":1004,"apk":2013,"q":"The financial collapse has badly damaged Romney's strongest argument: that business experience is exactly what Washington needs. He insists that understanding markets makes him uniquely qualified to repair them. How do you answer?","a":["Knowing how markets work is not the same thing as knowing whom they should work for.","Treat his expertise seriously and challenge the policies rather than the man.","Say the crisis proves businessmen should never be allowed near government.","Walk voters through deregulation, leverage, and foreclosure in plain English and ask Romney to defend the system piece by piece."]},{"qpk":1005,"apk":2017,"q":"Romney and Manchin close by promising steady hands after a frightening year. What do you say on Election Eve?","a":["Steady hands are useful only if they are steering somewhere different.","Make the final appeal about wages, homes, health care, and peace rather than either opponent.","Say Romney understands balance sheets but has never understood ordinary people.","Promise a broad administration and remind voters that change does not require chaos."]}],"romney-mccain":[{"qpk":1011,"apk":2041,"q":"Some days later, Romney stunned the party by selecting John McCain. Republicans call it a reunion of the party's managerial and national-security wings. The ticket looks formidable on paper, though it also looks a lot like the Republican establishment assembled on one stage. What do we do?","a":["Respect both men and immediately define the election around policy rather than biography.","Argue that two establishment résumés do not add up to a new direction.","Attack McCain as an aging Washington insider and Romney as a corporate one.","Make the economy the centerpiece before they can make experience the centerpiece."]},{"qpk":1012,"apk":2045,"q":"Romney says he understands the economy; McCain says the ticket has the experience to protect the country. The moderator asks what experience you can offer that compares. How do you answer?","a":["Judgment. I opposed the war and the financial rules that brought us here before either man did.","I have served in Congress for more than a decade; experience is not their private property.","Their combined years in business and Washington are exactly the problem.","Do not compete on résumés. Explain what you would actually do in the first hundred days."]},{"qpk":1013,"apk":2049,"q":"McCain is preparing to make the vice-presidential debate a seminar on national security. How should your running mate answer?","a":["Show respect for his service, then challenge the judgment behind Iraq and the broader interventionist consensus.","Make his age and long Washington career the issue.","Keep returning to the economy, where McCain is less comfortable.","Argue that experience without skepticism is how bad policies become permanent."]},{"qpk":1014,"apk":2053,"q":"The recession has undercut Romney's business pitch and tied McCain to a deeply unpopular Washington. They respond by saying this is precisely the moment for experienced leadership. What is the best contrast?","a":["Experience should be judged by results, not accumulated like seniority.","Offer a sober rescue plan and concede that both men have useful experience.","Say anyone who spent this long in Washington or finance forfeited the right to lead.","Focus narrowly on homeowners and jobs; let voters draw the broader conclusion themselves."]},{"qpk":1015,"apk":2057,"q":"Romney and McCain close with competence, patriotism, and continuity without Bush. What is your final response?","a":["You cannot promise a break with the old order by staffing the ticket with its most familiar faces.","End positively: peace, economic security, health care, and constitutional government.","Make a last appeal to voters who admire McCain personally but disagree with him politically.","Warn that the safest-looking choice can still preserve the policies that made the country unsafe."]}],"mccain-lieberman":[{"qpk":1016,"apk":2061,"q":"Some days later, John McCain chose Joe Lieberman, casting the ticket as a national-unity answer to an extraordinary year. The symbolism is powerful, but conservatives are irritated and anti-war voters see two of Iraq's loudest defenders. How should we react?","a":["Respect the symbolism while challenging the policies beneath it.","Make the Iraq War the unavoidable center of the new ticket.","Call them two Washington lifers trying to pass themselves off as insurgents.","Ignore Lieberman and make McCain answer for the Republican record."]},{"qpk":1017,"apk":2065,"q":"McCain wants the debate to be about service, courage, and experience. Hitting him as a Washington insider is tempting, but you have been in the House since 1997. Which contrast actually works?","a":["Judgment matters more than seniority: Iraq, civil liberties, and the economy give us a record to compare.","Washington has failed because men like McCain stayed too long; my own years there only prove I know it firsthand.","Make his age and years in office the centerpiece.","Do not attack his biography at all. Present a calm governing plan and let the contrast emerge."]},{"qpk":1018,"apk":2069,"q":"Lieberman will accuse your running mate of making the Democratic Party unsafe and unserious. How should the exchange be handled?","a":["Answer calmly and force him to defend the assumptions behind his foreign policy.","Make his break with the Democratic Party the issue.","Pivot to wages and health care rather than relitigating Iraq for ninety minutes.","Let our running mate defend the anti-war movement without apology."]},{"qpk":1019,"apk":2073,"q":"The crash has turned McCain's long Washington career from an asset into a complication. He insists that bipartisanship is exactly what the crisis requires. How do you answer?","a":["Bipartisan mistakes are still mistakes.","Praise cooperation where it helps and explain exactly where the old consensus failed.","Say Washington experience itself caused the collapse.","Ask why relief for banks is practical while relief for homeowners is ideological."]},{"qpk":1020,"apk":2077,"q":"McCain and Lieberman finish with a solemn appeal to unity and sacrifice. What is our final message?","a":["Unity has to include the people who have been asked to sacrifice for everybody else.","Speak softly and emphasize readiness to govern.","Return to the anti-war case that first distinguished this campaign.","Say national unity cannot become another name for permanent agreement with Washington."]}],"mccain-palin":[{"qpk":1021,"apk":2081,"q":"Some days later, McCain surprised the country by choosing Alaska Governor Sarah Palin. Conservatives are energized and the press is fascinated. Democrats are already questioning her readiness, but going too hard could look condescending. What do we do?","a":["Keep the focus on McCain and Bush rather than turning Palin into a celebrity.","Question her readiness carefully and with specific questions.","Treat her outsider image as legitimate and compete for the same voters.","Make McCain's judgment in selecting her the issue rather than Palin herself."]},{"qpk":1022,"apk":2085,"q":"McCain leans on service and experience, then turns the question around: what has Dennis Kucinich ever administered beyond Cleveland? Which attack do you make?","a":["Judgment on Iraq and civil liberties; experience is useful only when it produces good decisions.","Point to my years in Congress and my time as mayor, without pretending either is a governorship.","Call McCain old, tired, and trapped in the past.","Shift entirely to the economy and refuse the résumé contest."]},{"qpk":1023,"apk":2089,"q":"Palin intends to portray your running mate as an extremist while presenting herself as the authentic outsider. How should the debate proceed?","a":["Ask precise policy questions and avoid any hint of condescension.","Attack her as hopelessly inexperienced for national office.","Treat it as a contrast between two outsider movements and let voters judge the substance.","Keep returning to McCain's record and deny Palin the spotlight."]},{"qpk":1024,"apk":2093,"q":"The recession has damaged McCain, but Palin's anti-elite rhetoric gives the ticket a way to channel public anger. What is the closing economic argument?","a":["Separate respect for angry voters from acceptance of Republican economics.","Offer a practical recovery plan and say almost nothing about Palin.","Mock the idea that a Republican ticket can suddenly become anti-establishment.","Ask which campaign was warning about concentrated economic power before the banks collapsed."]},{"qpk":1025,"apk":2097,"q":"The Republicans close with McCain's experience and Palin's energy. What is our final response?","a":["America needs judgment and a plan, not simply a résumé paired with a sensation.","Offer reassurance and leave Palin out of the closing argument.","Ask voters which outsider campaign has actually challenged entrenched power.","Frame McCain's selection as a gamble, but avoid predicting what kind of president Palin would be."]}],"giuliani-jindal":[{"qpk":1026,"apk":2101,"q":"Some days later, Rudy Giuliani introduced Louisiana Governor Bobby Jindal as his running mate. Republicans call him the future of the party, and the coverage is strong. Giuliani gets security credentials; Jindal gets youth and policy fluency. Where do we start?","a":["Acknowledge Jindal's talent and keep attention on Giuliani's record.","Question whether Jindal's brief statewide résumé prepares him for the presidency.","Pivot immediately to wages and the economy rather than accept Giuliani's security frame.","Argue that a fresh face cannot modernize the same Republican program."]},{"qpk":1027,"apk":2105,"q":"Giuliani wants the debate to revolve around leadership after catastrophe. His weakness is that he has spent years speaking about crisis far more than economics. How do you exploit it without sounding dismissive of 9/11?","a":["Respect his leadership after the attacks, then force him onto wages, housing, and financial regulation.","Say Giuliani has built an entire career from one terrible day.","Challenge his civil-liberties record and governing temperament.","Open the opposition-research folder and ask what kind of judgment surrounded his New York political circle."]},{"qpk":1028,"apk":2109,"q":"Jindal will present your running mate as ideological and himself as a policy-minded reformer. Calling him inexperienced is tempting, but you have never won statewide office yourself. What is the approach?","a":["Meet him on policy detail and never mention his age.","Attack his lack of experience anyway; voters need to imagine him becoming president.","Contrast his social conservatism with the practical problems facing families.","Keep the debate centered on Giuliani so Jindal cannot become the ticket's fresh start."]},{"qpk":1029,"apk":2113,"q":"The crash has hurt Republicans, but Giuliani is weathering it better than most because his campaign was never built around economics. He now promises decisive crisis management. What do you say?","a":["Decisiveness is not an economic program; make him explain the numbers.","Acknowledge his crisis image and present a more detailed recovery plan.","Tie Wall Street excess to every wealthy New Yorker Giuliani has ever known.","Argue that fear is being used to avoid a debate he is less prepared to have."]},{"qpk":1030,"apk":2117,"q":"Giuliani and Jindal close by offering crisis leadership joined to generational change. What is our final message?","a":["A new generation deserves new policies, not merely younger packaging.","Stress calm competence and constitutional limits.","Make the election about economic security rather than personality.","Say courage after tragedy does not settle every question about governing a country."]}],"giuliani-frist":[{"qpk":1031,"apk":2121,"q":"Some days later, Giuliani selected former Senate Majority Leader Bill Frist. Republicans say the ticket combines executive leadership, Washington experience, and reassurance for social conservatives. It also combines two very different political identities. What do we do?","a":["Keep attention on the Bush-era record both men must defend.","Highlight the bargain asking conservatives to overlook Giuliani's social record.","Treat Frist as conventional and pivot to the economy.","Portray the ticket as every Republican establishment faction squeezed onto one stage."]},{"qpk":1032,"apk":2125,"q":"Giuliani presents himself as the executive who makes hard decisions. The economy is not his natural terrain, but simply calling him ignorant could look cheap. Which contrast belongs in the debate?","a":["Ask detailed economic questions and let the gaps appear without announcing them.","Make civil liberties and executive power the central contrast.","Say his entire national résumé consists of 9/11.","Use his New York political associations to question judgment, then move back to policy."]},{"qpk":1033,"apk":2129,"q":"Frist plans to challenge your running mate on health care, values, and readiness. What do you want emphasized?","a":["Health care: make the physician defend a system leaving millions uninsured.","Bring up his nationally televised intervention in the Terri Schiavo case as a question of judgment.","Attack him as another Washington insider.","Avoid personal history and make the debate about how each ticket would actually govern."]},{"qpk":1034,"apk":2133,"q":"The financial crisis weakens the Republican brand, but Giuliani still benefits from his reputation for command. Frist says your reforms would create even more instability. What is the response?","a":["Command without economic understanding is not competence.","Explain the first steps of reform rather than defending every long-term proposal.","Ask why instability for homeowners is accepted while instability for insurers and banks is treated as intolerable.","Say their institutions had authority, expertise, and every opportunity—and still failed."]},{"qpk":1035,"apk":2137,"q":"The Republican ticket closes as the adult, experienced alternative. What do you say on Election Eve?","a":["Adults accept responsibility for results.","Reassure voters that reform will be orderly and deliberate.","Make health care and economic security the final contrast.","Argue that establishment approval and public trust are not the same thing."]}],"perry-collins":[{"qpk":1036,"apk":2141,"q":"Some days later, Rick Perry surprised conservatives by selecting Maine Senator Susan Collins. Commentators think she could soften Perry with suburban independents. Calling the pairing incoherent is easy; convincing voters of that is harder. What do we do?","a":["Attack Perry's record and leave Collins largely alone.","Force Collins to defend Perry's hardest positions.","Appeal directly to moderates who respect Collins but distrust the platform.","Argue that moderation used as decoration is not moderation in government."]},{"qpk":1037,"apk":2145,"q":"Perry wants a values fight and speaks in broad, confident strokes. His advisers know detailed policy exchanges are less comfortable territory. How do you handle the debate?","a":["Keep asking for specifics—costs, dates, agencies, and what exactly he would sign.","Attack him as too inexperienced for the presidency.","Refuse the culture war and turn every answer back to wages and health care.","Go after his personality and dare him to lose his temper."]},{"qpk":1038,"apk":2149,"q":"Collins will portray your running mate as less pragmatic and less bipartisan than herself. What should the vice-presidential debate do?","a":["Acknowledge her reputation, then ask which Perry policies she is actually prepared to implement.","Attack Collins for being insufficiently conservative and try to split the Republican base.","Challenge her record from the left, vote by vote.","Keep the focus on Perry rather than granting Collins ownership of the ticket."]},{"qpk":1039,"apk":2153,"q":"The recession helps us, but Perry can credibly blame Washington because he governs Texas and rarely made economics his national calling card. Collins reinforces that distance. What is the closing argument?","a":["Make Perry describe what his broad anti-Washington slogans mean for the banking system.","Offer a narrow recovery plan and praise Collins where appropriate.","Say Texas economics caused the national crisis.","Ask why accountability for Wall Street is divisive while foreclosure is treated as private misfortune."]},{"qpk":1040,"apk":2157,"q":"Perry and Collins close by asking voters to choose balance over ideological risk. What is our final message?","a":["Balance between two incompatible instincts is not necessarily a governing philosophy.","Reassure voters that our administration will include practical and independent voices.","Focus entirely on economic recovery and leave Collins alone.","Say the greater risk is giving the same party another chance to define the rules."]}],"perry-pawlenty":[{"qpk":1041,"apk":2161,"q":"Some days later, Perry announced Minnesota Governor Tim Pawlenty. There is nothing flashy about the choice, and Republicans say that is precisely the point. Pawlenty gives Perry a calmer Midwestern voice. What do we do?","a":["Keep Pawlenty secondary and define Perry first.","Challenge Pawlenty's economic record and Midwestern credentials.","Use the selection to intensify organizing in Minnesota, Wisconsin, and Iowa.","Argue that a quieter style does not make the underlying program moderate."]},{"qpk":1042,"apk":2165,"q":"Perry is trying to turn the debate into a values fight. When pressed beyond broad themes, however, he can become less comfortable. What is our strategy?","a":["Ask concrete follow-ups until slogans have to become policy.","Attack him as an inexperienced governor who is not ready for Washington.","Talk labor, wages, and manufacturing and deny him the culture-war terrain.","Make jokes about his intelligence and hope one sticks."]},{"qpk":1043,"apk":2169,"q":"Pawlenty plans to say your running mate understands activists better than ordinary Midwestern families. How should the debate be handled?","a":["Answer with specific economic policies and local consequences.","Challenge Pawlenty's own claim to represent working families.","Keep the focus on Perry and avoid a regional-authenticity contest.","Let our running mate make an unapologetic anti-war appeal."]},{"qpk":1044,"apk":2173,"q":"The crash improves our position, but Perry can stand outside Washington and Pawlenty can sound reassuring. What is the best economic contrast?","a":["Force Perry to turn his anti-Washington language into an actual recovery program.","Offer a measured plan aimed at manufacturing and homeowners.","Blame every Republican governor for Wall Street.","Argue that the crisis is already a class conflict; only one side has lacked representation."]},{"qpk":1045,"apk":2177,"q":"The Republican ticket closes as conservative conviction balanced by Midwestern normalcy. What is our final message?","a":["Normalcy is not enough when the normal economy has collapsed.","Offer a calm, practical appeal to industrial states.","Return to peace, wages, and health care.","Ask voters whether a softer voice changes the direction of the ticket."]}],"perry-pataki":[{"qpk":1046,"apk":2181,"q":"Some days later, Perry selected former New York Governor George Pataki. Republicans say the ticket combines conservative conviction with big-state executive experience. Pataki is meant to reassure precisely the voters Perry worries. How do we respond?","a":["Focus on Perry and avoid answering the moderation question for Republicans.","Force Pataki to defend Perry before Northeastern suburban voters.","Attack both governors as creatures of donors and statehouse insiders.","Pivot to the economy and let the ticket's internal contrast speak for itself."]},{"qpk":1047,"apk":2185,"q":"Perry wants a values election; Pataki gives him a practical Northeastern validator. Perry's broad answers leave openings, but overplaying them could look smug. Which debate strategy works?","a":["Ask for specifics and keep the tone matter-of-fact.","Attack Perry's lack of national experience.","Use Pataki's presence to argue that Perry cannot defend his own moderation.","Refuse both frames and present a disciplined recovery program."]},{"qpk":1048,"apk":2189,"q":"Pataki will portray your running mate as incapable of governing beyond the activist left. How should the debate proceed?","a":["Challenge his record while emphasizing our ticket's actual governing plans.","Ask why Pataki is lending moderation to positions he once avoided.","Keep the exchange on the crisis and Wall Street.","Attack Pataki as yesterday's Republican and hope voters agree."]},{"qpk":1049,"apk":2193,"q":"The crash helps Democrats, but Perry remains less exposed than businessmen or senators. Pataki, meanwhile, knows New York finance well enough to sound credible. What is the closing response?","a":["Distinguish knowing Wall Street from being willing to confront it.","Offer a restrained first-year recovery program.","Treat Pataki's New York connections as proof of corruption.","Force Perry to explain his own economic program instead of borrowing Pataki's vocabulary."]},{"qpk":1050,"apk":2197,"q":"Perry and Pataki close as an ideologically balanced team of governors. What is our Election Eve message?","a":["A balanced ticket can still move the country in the wrong direction.","Stress competence, cabinet breadth, and an orderly transition.","Make the final appeal about wages, homes, and peace.","Say Republicans are offering two styles of the same political economy."]}],"forbes-gingrich":[{"qpk":1051,"apk":2201,"q":"Several days after the convention finally broke, Steve Forbes announced former House Speaker Newt Gingrich as his running mate. Republicans call them two of the conservative movement's deepest thinkers. The ticket is unusual, ideological, and very wealthy in both ideas and baggage. How do we begin?","a":["Treat Forbes seriously and make the campaign a debate over what his economic program would actually do.","Paint the pair as relics of the 1990s before they can introduce themselves as reformers.","Attack Forbes as a rich man who could never understand ordinary Americans.","Welcome the ideological clarity and argue that voters finally have an honest choice."]},{"qpk":1052,"apk":2205,"q":"Forbes turns the first debate into a lecture on growth, taxes, and markets. He is comfortable with theory and less comfortable when politics becomes personal. What is the best way through?","a":["Ask who gains, who pays, and what happens to a family living paycheck to paycheck.","Mock the flat tax until he loses his composure.","Match him whiteboard for whiteboard and debate every economic assumption.","Say a publishing heir has no standing to lecture working people about sacrifice."]},{"qpk":1053,"apk":2209,"q":"Gingrich will try to overwhelm your running mate with history, statistics, and sheer volume. His weakness is not a lack of preparation but a long and polarizing record. How should the debate proceed?","a":["Let him talk, then connect the 1990s shutdown politics to the governing style Republicans are offering again.","Attack his personal life and ethics history.","Try to out-detail him on every subject.","Keep returning to the present crisis and ask what any of his old theories mean for a family losing its home."]},{"qpk":1054,"apk":2213,"q":"The financial system is collapsing around a ticket built almost entirely around free-market economics. Forbes insists the answer is more growth, lower taxes, and fewer distortions. What do you say?","a":["Do not gloat. Calmly ask voters whether the philosophy that promised self-correction deserves another experiment.","Say this proves capitalism itself has failed.","Walk through the flat tax and deregulation agenda line by line and connect it to the crisis.","Attack Forbes personally as a billionaire trying to buy the presidency."]},{"qpk":1055,"apk":2217,"q":"Forbes and Gingrich close by saying only bold conservative ideas can revive American growth. What is your final response?","a":["Boldness is not the issue; whether the idea survived contact with reality is.","End positively on peace, health care, wages, and democratic accountability.","Tell voters the Republican convention nominated two men from another decade.","Say the country cannot afford another economic theory seminar while families are losing homes."]}]};

function k08EnsureCandidateRecord(pk, fields) {
    let rec = k08Record(pk);
    if (!rec) {
        rec = {model:"campaign_trail.candidate",pk:pk,fields:{election:3,priority:30,color_hex:"#FF0000",secondary_color_hex:"#FFA0A0",is_active:0,description:"",electoral_victory_message:"n/a",electoral_loss_message:"n/a",no_electoral_majority_message:"n/a",running_mate:true,...fields}};
        campaignTrail_temp.candidate_json = campaignTrail_temp.candidate_json || [];
        campaignTrail_temp.candidate_json.push(rec);
    }
    return rec;
}
function k08EnsureForbesRecords() {
    k08EnsureCandidateRecord(52,{
        first_name:"Newt",last_name:"Gingrich",party:"Republican",state:"Georgia",
        image_url:"https://i.imgur.com/mlYwPL8.png",
        description_as_running_mate:"<p>Former House Speaker Newt Gingrich gives Forbes an aggressive movement-conservative partner with a long record, a talent for policy argument, and just as much political baggage.</p>",
        candidate_score:1
    });
    const qdefs = K08_BRANCH_COPY["forbes-gingrich"] || [];
    for (const row of qdefs) {
        if (!(campaignTrail_temp.questions_json||[]).some(q=>Number(q.pk)===Number(row.qpk))) {
            campaignTrail_temp.questions_json.push({model:"campaign_trail.question",pk:row.qpk,fields:{description:row.q}});
        }
        row.a.forEach((text,i)=>{
            const apk=row.apk+i;
            if (!(campaignTrail_temp.answers_json||[]).some(a=>Number(a.pk)===Number(apk))) {
                campaignTrail_temp.answers_json.push({model:"campaign_trail.answer",pk:apk,fields:{question:row.qpk,description:text}});
            }
        });
    }
}
function k08SetAnswerGlobal(answerPk, value) {
    campaignTrail_temp.answer_score_global_json = campaignTrail_temp.answer_score_global_json || [];
    let rec = campaignTrail_temp.answer_score_global_json.find(x=>Number(x?.fields?.answer)===Number(answerPk) && Number(x?.fields?.affected_candidate)===16);
    if (!rec) {
        rec={model:"campaign_trail.answer_score_global",pk:500000+Number(answerPk),fields:{answer:Number(answerPk),candidate:16,affected_candidate:16,global_multiplier:Number(value)}};
        campaignTrail_temp.answer_score_global_json.push(rec);
    } else rec.fields.global_multiplier=Number(value);
}
function k08SetFeedback(answerPk, text) {
    campaignTrail_temp.answer_feedback_json = campaignTrail_temp.answer_feedback_json || [];
    let rec = campaignTrail_temp.answer_feedback_json.find(x=>Number(x?.fields?.answer)===Number(answerPk));
    if (!rec) {
        rec={model:"campaign_trail.answer_feedback",pk:600000+Number(answerPk),fields:{answer:Number(answerPk),answer_feedback:String(text)}};
        campaignTrail_temp.answer_feedback_json.push(rec);
    } else rec.fields.answer_feedback=String(text);
}
function k08SetBaseQuestion(pk, qtext, answers, feedback, scores) {
    const q=(campaignTrail_temp.questions_json||[]).find(x=>Number(x.pk)===Number(pk));
    if(q?.fields) q.fields.description=qtext;
    const apks = {17:[65,66,67,68],18:[69,70,71,72],19:[73,74,75,76],22:[85,86,87,88]}[pk] || [];
    apks.forEach((apk,i)=>{
        const a=(campaignTrail_temp.answers_json||[]).find(x=>Number(x.pk)===Number(apk));
        if(a?.fields && answers?.[i]!=null) a.fields.description=answers[i];
        if(feedback?.[i]!=null) k08SetFeedback(apk,feedback[i]);
        if(scores?.[i]!=null) k08SetAnswerGlobal(apk,scores[i]);
    });
}
const K08_OPP_RESEARCH = {
  mccain:{
    q:"Our opposition researchers have dropped a thick folder on McCain's career onto the desk. Some of it is ancient history, and some of it can come right back at a congressman who's been in Washington since 1997. Where do you want to begin?",
    a:["Revisit the Keating Five and make the case that his reformer image is more complicated than he likes to admit.","Forget the old scandals. I want to contrast his judgment on Iraq with mine.","He's been in Washington forever. Make him defend what all those years actually produced."],
    f:["The story is real and it complicates the reformer image, but it also feels old. We get coverage, not a knockout.","This is the cleanest contrast available. McCain has experience; your argument is that experience repeatedly produced the wrong judgment.","Careful. You've been in Washington for more than a decade yourself. The attack lands, but Republicans have an easy answer."],
    s:[.008,.015,.003]
  },
  romney:{
    q:"We know we can hit Romney with some of our opposition research. But we need to be careful here. Where do you want to begin?",
    a:["Start with Bain Capital. Go case by case through the vulture capitalist firm and talk about the workers, the debt, and who was left holding the bag.","Look, Ted Kennedy mopped the floor with this guy in a debate. Get him on the phone, let's get some good perspective here.","Go through the changes in his positions. If Romney wants to reinvent himself again, make him explain every version."],
    f:["This gives reporters something concrete to examine and keeps the argument on decisions rather than envy. Romney has answers, but he has to spend time giving them.","Teddy gives you a few pointers, but it's nothing we didn't already know. He agrees to appear with you for a couple rallies, so I guess that's nice.","The flip-flops are real and easy to explain. They are not fatal by themselves, but they make Romney spend valuable time defending which version of himself voters should believe."],
    s:[.017,0,.008]
  },
  perry:{
    q:"Our opposition researchers have plenty of material from Perry's years in Texas, but nothing that looks like an obvious knockout blow. He's strongest talking in broad strokes about faith, growth and a broken Washington. Where do you want us to begin?",
    a:["I've watched Perry in those primary debates, and I've got a feeling he doesn't like getting into specifics. Let's test that. Costs, dates, details. Keep pressing him until the broad talking points aren't enough.","He's a governor from Texas who's never served a day in Washington. Let's make the case that he simply isn't experienced enough for the presidency.","Keep digging through his appointments and donors in Texas. Somebody who's been governor that long has to have something worth putting on television."],
    f:["The media picks up on it, and it does seem to work. Reporters start pressing Perry for more specifics themselves, and his broad pitch doesn't always hold up as well under follow-up questions. Nice catch, Dennis.","That doesn't last long. Perry has been Governor of Texas for years, while you've never held statewide office yourself. Republicans are more than happy to compare the two resumes.","We find plenty worth asking questions about. The problem is explaining any of it in thirty seconds. There's smoke here, Dennis, but nothing that catches fire nationally."],
    s:[.018,-.006,.006]
  },
  giuliani:{
    q:"Our opposition researchers have spent weeks digging through Giuliani's years in New York. The problem is that the national press has already examined seemingly every divorce, feud and questionable associate he's ever had. There's still plenty here, but what do you actually want us to use?",
    a:["Ya know, in the debates during the primary Ron Paul really clobbered him on 9/11. Let's cut that into something.","Forget the gossip. Look at policing, civil liberties and how he actually ran New York. If Giuliani wants to campaign on his record as mayor, let's give voters the whole record.","There is old television footage everyone keeps laughing about. Fine. Show me that."],
    f:["'Clobbered' is a stretch. Sure, Paul was right on the substance of blowback and 9/11, but Giuliani clearly won the emotional angle in that debate. It's far from the knockout punch we needed. Plus, now he gets to talk about 9/11 again.","That's substantive and defensible. There's plenty in Giuliani's mayoral record for us to challenge. Just remember that you're accepting a fight over New York and public safety with a man whose political career was built on exactly those subjects.","Oh, it's real. At the 2000 Inner Circle dinner, Giuliani appeared in drag for a comedy sketch while Donald Trump played an aggressively flirtatious suitor. Cable news can't resist the footage. It's funny, Dennis, but now some of our own people are wondering why the hell we're pushing it."],
    s:[-.002,.014,-.004]
  },
  forbes:{
    q:"Our opposition researchers have run into an unusual problem with Forbes. He's spent years publishing his opinions and already ran for President twice, so there aren't many surprises left to uncover. If there's no hidden scandal waiting for us, where do you want to begin?",
    a:["Start with the flat tax. Don't give people charts and percentages. Show me what Steve Forbes' economic plan actually means for a cashier, a machinist or a family trying to pay their mortgage.","The guy already ran for President twice and couldn't even get close. Dig up the old footage and remind everyone that Republicans rejected Steve Forbes themselves.","He's a multimillionaire heir running on tax cuts that would benefit people like himself. Forget the old campaigns. Let's make that the story."],
    f:["Now we've got something. Instead of arguing economic theory with Forbes, you're making him explain what that theory means to somebody's paycheck. He has answers, Dennis, but at least they're answers we can argue with.","Dennis, your 2004 campaign went nowhere, and you pretty much won this nomination by process of elimination. Or... I mean... anyway, Republicans waste no time pointing out the obvious hypocrisy, and this one hurts us more than Forbes.","Careful. Not everyone is on board with your economic proposals either. Attacking Forbes's platform still requires us to explain why yours is better, and making his wealth the whole argument doesn't do that work for us."],
    s:[.020,-.010,.001]
  }
};
function k08InstallGeneralElectionFlavor(nominee) {
    const r=K08_OPP_RESEARCH[nominee] || K08_OPP_RESEARCH.mccain;
    k08SetBaseQuestion(17,r.q,r.a,r.f,r.s);
    k08SetBaseQuestion(18,
      "July 2008: Republicans are trying to make crime and public order a test of whether you are too soft for the presidency. We can answer with policy, or remind people that Cleveland politics was not exactly a seminar room. What do you say?",
      [
        "Talk about sensible gun laws, background checks, and keeping weapons away from people who should not have them.",
        "Make the case for criminal-justice reform, prevention, and treatment without pretending violent crime is not real.",
        "Emphasize community policing, competent local government, and federal support for cities.",
        "I'm not worried about looking weak. Remember when I was Mayor of Cleveland?"
      ],
      [
        "It is a conventional Democratic answer and reassures some suburban voters, though Republicans immediately argue you are coming for lawful gun owners.",
        "The answer excites reformers and gives Republicans an opening to call you soft. The policy debate is real, and so is the political risk.",
        "This is hard to caricature. It is also not the kind of answer that changes the race by itself.",
        "The story catches much of the country by surprise: while you were mayor, Cleveland organized-crime figures were tied to a plot to have you killed after your battles with powerful local interests around the municipal electric utility. The anecdote does more for your toughness than another ten-point crime plan ever could, even if the segue is a little theatrical."
      ],
      [0.006,0.005,0.009,0.017]
    );
    k08SetBaseQuestion(19,
      "July 2008: A conservative radio host has gone personal, joking that Elizabeth must have married you for money and calling her a 'trophy wife.' The line is ugly, but it is spreading because the contrast between the two of you has always attracted tabloid attention. How do you respond?",
      [
        "Don't. Elizabeth is not running for office, and repeating the insult only gives it oxygen.",
        "Laugh: 'If Elizabeth married me for money, somebody owes her an apology.'",
        "Defend Elizabeth's work and say anyone who reduces her to your wife has not bothered to learn who she is.",
        "Demand that the Republican ticket personally denounce the remark."
      ],
      [
        "The story burns for a day and fades. Some supporters wanted a sharper defense, but refusing the bait looks presidential.",
        "The joke works because the premise is absurd: you have never been remotely wealthy by presidential-candidate standards. Even unfriendly reporters laugh, and the original attack looks nastier in retrospect.",
        "This turns an insult into an introduction to Elizabeth on your own terms. It is sincere, if a little more personal than the campaign wanted to become.",
        "The demand keeps the insult alive and lets Republicans complain that you are manufacturing outrage over a radio host they do not control."
      ],
      [0.010,0.019,0.014,-0.004]
    );
    k08SetBaseQuestion(22,
      "September 15, 2008: You wake up to a dozen missed calls. One message from an adviser simply says, 'Turn on the television.' Lehman Brothers has filed for bankruptcy. Credit markets are freezing, Wall Street is panicking, and nobody—not your campaign, not the Republicans, not the White House—knows how far this goes. Every speech planned yesterday suddenly feels obsolete. What do you say first?",
      [
        "Do not celebrate being right. Tell frightened families what the government must do in the next forty-eight hours and what it must never do again.",
        "This is the bill for decades of deregulation. Say it plainly and make the campaign a referendum on the economic establishment.",
        "Call for emergency protections for deposits, payroll, mortgages, and credit while refusing a blank check for executives.",
        "Say very little until we know more. A presidential candidate should not improvise during a panic."
      ],
      [
        "The restraint matters. Your warnings about concentrated financial power are suddenly being replayed everywhere, and a practical response makes them sound less like protest rhetoric and more like foresight.",
        "The anger is real and voters are ready to hear it. Some financial reporters call the speech ideological, but for the first time that word is not automatically fatal to you.",
        "This is difficult to caricature as either laissez-faire or a Wall Street bailout. It also begins moving frightened middle-class voters who had dismissed you months ago.",
        "The caution is defensible, but the moment is moving faster than the campaign. You still benefit from the collapse simply because the political terrain has changed beneath both parties."
      ],
      [0.030,0.024,0.028,0.010]
    );
    if (nominee === "forbes") {
        const q20=(campaignTrail_temp.questions_json||[]).find(x=>Number(x.pk)===20);
        if(q20?.fields) q20.fields.description="September 2008: The brokered convention left Republicans almost no time to introduce Forbes and Gingrich before the fall campaign. Polling is volatile, voters are exhausted, and both tickets are trying to define a race that barely had time to begin. What is the plan?";
    }
}
const K08_BRANCH_SCORE_PATTERN = [0.012,0.018,-0.004,0.010, 0.018,0.006,0.012,0.015, 0.014,-0.005,0.010,0.012, 0.016,0.012,-0.006,0.019, 0.012,0.014,0.004,0.011];
function k08InstallBranchMechanics() {
    for (const [ticket,rows] of Object.entries(K08_BRANCH_COPY)) {
        rows.forEach((row,ri)=>{
            row.a.forEach((text,ai)=>{
                const apk=row.apk+ai;
                const score=K08_BRANCH_SCORE_PATTERN[ri*4+ai] ?? 0.008;
                k08SetAnswerGlobal(apk,score);
                if (!(campaignTrail_temp.answer_feedback_json||[]).some(x=>Number(x?.fields?.answer)===apk)) {
                    k08SetFeedback(apk, score < 0 ? "The attack feels good in the room, but the counterargument writes itself. Our own résumé makes this line much less clean than it sounded in debate prep." :
                      score < 0.007 ? "There is a point here, but the campaign pushes it a little too far. The opponent takes some damage and so do we." :
                      score > 0.017 ? "This lands because it attacks the opponent's actual vulnerability without pretending Dennis is immune to the same standard." :
                      "A defensible line. It moves some voters, but there is no magic answer in a campaign this strange.");
                }
            });
        });
    }
    const special={
      2066:"The line about your own House service blunts the easiest Republican comeback. McCain still owns the experience advantage; you simply refuse to let longevity become the same thing as judgment.",
      2086:"Your mayoral and congressional résumé is real, but McCain's is longer and more conventional. The honesty keeps the answer from becoming a trap.",
      2090:"This works. Palin is forced into specifics without being mocked, and the contrast emerges on television instead of in your own rhetoric.",
      2091:"Republicans immediately point out that Dennis Kucinich has never won statewide office either. Palin takes a hit on readiness, but the attack does not come free.",
      2106:"This is the trap. Jindal's résumé is short, but he is a sitting governor; Kucinich has never won statewide office. The press spends as much time on your experience as his.",
      2126:"Giuliani is much happier talking about command than household economics. Repeatedly asking for numbers exposes the imbalance without requiring you to call him ignorant.",
      2129:"Frist's medical background gives him authority, but the health-care system is unpopular enough that forcing him to defend it turns his strength into a complicated asset.",
      2145:"Perry never produces one catastrophic answer, but the accumulation matters. Asking for specifics proves more effective than calling him stupid ever could.",
      2146:"That is a rough exchange. Perry has been governor of Texas for years; Dennis Kucinich has never won statewide office. The intended experience attack turns around on us.",
      2165:"This is exactly the pressure point. Perry's confidence remains intact, but the more specific the questions become, the less effortless the performance looks.",
      2168:"The insult gets laughs from people already voting for us. Everyone else mostly wonders why a presidential candidate is calling his opponent stupid.",
      2185:"The tone saves this. Perry has to answer detailed questions while you never explicitly tell the audience what conclusion to draw.",
      2205:"Forbes knows the theory cold. The question that bothers him is not what the model predicts, but what happens to a particular family while the model adjusts.",
      2206:"Forbes does not melt down, and the mockery makes him look more sympathetic than he did five minutes earlier.",
      2208:"The personal class attack is too easy. Forbes is rich; voters knew that before the debate. The campaign gains applause and not much else.",
      2213:"Gingrich is perfectly happy to discuss the 1990s. The useful part is connecting that history to a governing style rather than expecting the word 'shutdown' to end the debate.",
      2214:"There is plenty in Gingrich's personal and ethics history, but going there gives him an opening to accuse you of avoiding policy. The exchange becomes uglier than useful.",
      2217:"The lack of triumphalism is powerful. Forbes has to defend a free-market program while television screens are showing financial institutions collapsing behind him.",
      2218:"The rhetoric thrills the left and frightens nearly everybody else. A crisis that was helping us suddenly becomes a debate about whether Dennis Kucinich wants to abolish capitalism."
    };
    Object.entries(special).forEach(([pk,txt])=>k08SetFeedback(Number(pk),txt));
    const overrides={2091:-0.006,2106:-0.007,2146:-0.008,2168:-0.009,2206:0.002,2208:-0.004,2214:-0.004,2217:0.025,2218:-0.010,2145:0.022,2165:0.021,2185:0.019,2126:0.020};
    Object.entries(overrides).forEach(([pk,val])=>k08SetAnswerGlobal(Number(pk),val));
}
