k08EnsureCenterTicketBanner=function(){
  const key=campaignTrail_temp?.k08?.democraticVp||"before";
  const url=K08_BANNERS[key]||K08_BANNERS.before;
  let wrap=document.getElementById("k08_center_ticket_banner_wrap");
  if(!wrap){
    const els=Array.from(document.querySelectorAll("div,span,h1,h2,h3,h4,p"));
    const label=els.find(el=>{
      const t=String(el.textContent||"").replace(/\s+/g," ").trim().toLowerCase();
      return /^kucinich(?:\s*[\/\-–—]\s*|\s+)(party|democratic party|gravel|lee|paul|patrick|napolitano|feingold)$/.test(t)
        || t==="kucinich party"||t==="kucinich democratic party";
    });
    if(label){
      wrap=document.createElement("div");
      wrap.id="k08_center_ticket_banner_wrap";
      wrap.style.cssText="display:flex;align-items:center;justify-content:center;width:100%;min-height:94px;overflow:hidden;background:transparent;padding:2px 8px;box-sizing:border-box;";
      label.replaceWith(wrap);
    }
  }
  if(!wrap){
    const imgs=Array.from(document.querySelectorAll("#game_window img"));
    const dennis=imgs.find(i=>/SZhpnoj|WX9G1oX|0zCEmZ2|TCMMYkp|SZhpnoj/.test(String(i.src||"")));
    const rm=imgs.find(i=>/WWckXp3|33hgr4t|ewD6RhT|IQ0orxw|oU9d9uL/.test(String(i.src||"")));
    let host=null;
    if(dennis&&rm){let a=dennis.parentElement;while(a&&!a.contains(rm))a=a.parentElement;host=a;}
    if(host&&!host.querySelector("#k08_center_ticket_banner_wrap")){
      wrap=document.createElement("div");
      wrap.id="k08_center_ticket_banner_wrap";
      wrap.style.cssText="display:flex;align-items:center;justify-content:center;width:100%;min-height:94px;overflow:hidden;background:transparent;padding:2px 8px;box-sizing:border-box;";
      host.appendChild(wrap);
    }
  }
  if(wrap){
    let banner=wrap.querySelector("#k08_center_ticket_banner");
    if(!banner){
      banner=document.createElement("img");
      banner.id="k08_center_ticket_banner";
      banner.alt="Kucinich campaign ticket banner";
      banner.style.cssText="display:block;width:auto;max-width:96%;height:auto;max-height:88px;object-fit:contain;margin:4px auto 0 auto;";
      wrap.replaceChildren(banner);
    }
    banner.src=url;
  }
};

