function k08ReactiveProfile() {
    const v = campaignTrail_temp.k08 || {};
    const candidates = [
      ["security", Number(v.securityConcern||0)],
      ["anxiety", Number(v.voterAnxiety||0)],
      ["party", Math.max(0, -Number(v.partySupport||0))],
      ["media", Math.max(0, -Number(v.mediaRelationship||0))],
      ["conspiracy", Number(v.conspiracyHeat||0)]
    ].sort((a,b)=>b[1]-a[1]);
    return {
      dominant: candidates[0][0],
      score: candidates[0][1],
      securityHigh: Number(v.securityConcern||0) >= 4,
      anxietyHigh: Number(v.voterAnxiety||0) >= 6,
      conspiracyCrisis: Number(v.voterAnxiety||0) >= 6 && Number(v.conspiracyHeat||0) >= 3,
      partyWeak: Number(v.partySupport||0) <= -2,
      progressiveOpportunity: Number(v.progressiveTrust||0) >= 8 && Number(v.publicPerception||0) >= 5,
      vp: v.democraticVp || "gravel"
    };
}

function k08ReactiveTrackForSlot(slot) {
    const p = k08ReactiveProfile();
    if (slot === "reassurance") {
      if (p.conspiracyCrisis) return "conspiracy-crisis";
      if (p.securityHigh) return `security-${p.vp}`;
      if (p.anxietyHigh) return `anxiety-${p.vp}`;
      if (p.partyWeak) return `party-${p.vp}`;
      if (p.progressiveOpportunity) return `progressive-opportunity-${p.vp}`;
    }
    return "standard";
}

