function k08EnsureGlobalRecord(pk,m){
  let g=k08GlobalRecord(pk);
  if(!g){
    const rows=campaignTrail_temp.answer_score_global_json=campaignTrail_temp.answer_score_global_json||[];
    const nextPk=rows.reduce((mx,r)=>Math.max(mx,Number(r?.pk)||0),0)+1;
    g={model:'campaign_trail.answer_score_global',pk:nextPk,fields:{answer:Number(pk),candidate:16,affected_candidate:16,global_multiplier:Number(m)}};
    rows.push(g);
  } else {
    g.fields.global_multiplier=Number(m);
  }
  return g;
}
Object.entries(K08_CANONICAL_GLOBALS).forEach(([pk,m])=>k08EnsureGlobalRecord(Number(pk),m));

Object.entries({130:-.022,131:-.020,132:-.030}).forEach(([pk,m])=>k08EnsureGlobalRecord(Number(pk),m));
campaignTrail_temp.k08._dynamicEffects = campaignTrail_temp.k08._dynamicEffects || {};
campaignTrail_temp.k08._dynamicEffects[130]={voterAnxiety:2,mediaRelationship:-2,securityConcern:1};
