function k08AnswerRecord(pk){
  return (campaignTrail_temp.answers_json||[]).find(a=>Number(a.pk)===Number(pk));
}
function k08GlobalRecord(pk){
  return (campaignTrail_temp.answer_score_global_json||[]).find(a=>Number(a?.fields?.answer)===Number(pk) && Number(a?.fields?.affected_candidate)===16);
}
function k08ResolveOpponentTokens(text){
  if(typeof text !== "string") return text;
  const key=campaignTrail_temp?.k08?.republicanNominee;
  const last=K08_GOP?.[key]?.last || campaignTrail_temp?.opponent_last_name || "Republican nominee";
  return text.replace(/\{OPPONENT\}/g,last).replace(/\bOPPONENT\b/g,last);
}
function k08ResolveAllOpponentTokens(){
  (campaignTrail_temp.questions_json||[]).forEach(q=>{
    if(typeof q?.fields?.description === "string") q.fields.description=k08ResolveOpponentTokens(q.fields.description);
  });
  (campaignTrail_temp.answers_json||[]).forEach(a=>{
    if(typeof a?.fields?.description === "string") a.fields.description=k08ResolveOpponentTokens(a.fields.description);
  });
}
function k08SetReactiveQuestion(pk, description, answerPks, answerText, multipliers, effects, feedback){
  const q=(campaignTrail_temp.questions_json||[]).find(x=>Number(x.pk)===Number(pk));
  if(q?.fields) q.fields.description=k08ResolveOpponentTokens(description);
  answerPks.forEach((apk,i)=>{
    const a=k08AnswerRecord(apk); if(a?.fields) a.fields.description=k08ResolveOpponentTokens(answerText[i]);
    const g=k08GlobalRecord(apk);
    if(g?.fields && multipliers?.[i] != null) {
      const raw=Number(multipliers[i]);
      g.fields.global_multiplier=Number(((raw>0 ? raw*0.50 : raw<0 ? raw*1.20 : 0)).toFixed(5));
    }
    campaignTrail_temp.k08._dynamicEffects[Number(apk)] = effects?.[i] || {};
    if(feedback?.[i] && typeof k08SetFeedback==='function') k08SetFeedback(apk,feedback[i]);
  });
}
function k08ApplyDynamicEffect(answerPk){
  const fx=campaignTrail_temp.k08?._dynamicEffects?.[Number(answerPk)];
  if(!fx) return;
  Object.entries(fx).forEach(([key,val])=>{
    campaignTrail_temp.k08[key]=Number(campaignTrail_temp.k08[key]||0)+Number(val||0);
  });
  if (Object.prototype.hasOwnProperty.call(fx,'progressiveTrust')) {
    campaignTrail_temp.k08.kucinichPurity = Math.max(0, Number(campaignTrail_temp.k08.kucinichPurity||0) + Number(fx.progressiveTrust||0));
  }
}
function k08VpLabel(){
  return ({gravel:'Mike Gravel',lee:'Barbara Lee',paul:'Ron Paul',patrick:'Deval Patrick',napolitano:'Janet Napolitano',feingold:'Russ Feingold'})[campaignTrail_temp.k08.democraticVp] || 'your running mate';
}

function k08InstallClintonEndorsementQuestion(){
  const vp=campaignTrail_temp.k08.democraticVp||'gravel';
  const vpName=k08VpLabel();
  const power={
    napolitano:[.045,.033,.006,-.018],
    patrick:[.041,.031,.006,-.017],
    feingold:[.036,.029,.007,-.015],
    lee:[.027,.024,.008,-.012],
    gravel:[.015,.019,.010,-.008],
    paul:[-.004,.010,.012,-.002]
  }[vp] || [.018,.020,.008,-.010];
  const cost={napolitano:-1,feingold:-1,patrick:-1,lee:0,gravel:-1,paul:-3}[vp] ?? -1;
  const strongLine={
    napolitano:'Napolitano gives Clinton an easy opening: she can praise a serious governor on the ticket while presenting her endorsement as Democratic unity rather than ideological surrender.',
    patrick:'Patrick makes the ask relatively easy. Clinton can emphasize generational change and governing competence without pretending every faction of the party suddenly agrees.',
    feingold:'Feingold gives Clinton an easy unity argument: he is a sitting Democratic senator with a progressive record, but hardly somebody the party can dismiss as unserious.',
    lee:'Clinton agrees to go further, though the embrace is careful. Lee reassures the left more than the center, so the endorsement helps mostly by showing the party is no longer openly fractured.',
    gravel:'Clinton gives you more than before, but not a bear hug. Gravel makes the ticket difficult for her circle to sell as conventional Democratic governance.',
    paul:'This backfires inside the coalition. Clinton is unwilling to become the validator for a Kucinich-Paul ticket, and the very public courtship irritates Paul supporters who joined precisely to break with both party establishments.'
  }[vp];
  k08SetReactiveQuestion(18,
    `June 2008: Hillary Clinton has finally spoken about the general election, but only barely. She has urged Democrats to vote for the Democratic ticket without once saying your name. With ${vpName} now beside you, party leaders think a real Clinton endorsement could settle nervous donors and moderates. Do we ask her to go further?`,
    [69,70,71,72],
    [
      'Ask Clinton privately for a full-throated endorsement and a joint appearance. Make clear that a Kucinich administration will include the whole Democratic Party.',
      'Seek a unity appearance, but do not bargain over policy or personnel. She can endorse us on her terms and we can campaign on ours.',
      'Leave it alone. A reluctant endorsement is worse than no endorsement, and voters already know which party we belong to.',
      'Call the hesitation what it is. Democratic leaders cannot ask for unity while treating the nominee like an embarrassment.'
    ], power,
    [
      {partySupport:3,nationalUnity:2,publicPerception:2,securityConcern:-1,voterAnxiety:-1,progressiveTrust:cost},
      {partySupport:2,nationalUnity:1,publicPerception:1,voterAnxiety:-1},
      {progressiveTrust:1,publicPerception:0},
      {progressiveTrust:2,partySupport:-2,nationalUnity:-1,voterAnxiety:1}
    ],
    [
      vp==='paul'
        ? 'Clinton never responds to the request. A few days later she uploads a short YouTube video telling Democrats simply to “vote blue,” without mentioning you, Ron Paul, or the ticket by name. The silence says more than an explicit refusal probably would have.'
        : strongLine,
      vp==='paul'
        ? 'Clinton never agrees to the unity appearance. Instead, she posts a YouTube video urging people to “vote blue” and leaves it at that — no Kucinich, no Paul, no joint appearance. It is technically support for the Democratic ticket, but nobody mistakes it for an endorsement of this one.'
        : 'This works about as well as a negotiated truce can. Clinton appears with the ticket, praises Democratic priorities, and leaves the ideological differences conspicuously unexamined.',
      'There is no explosion, but there is no healing either. Activists like the independence; skeptical Democrats continue wondering why so many familiar party figures sound embarrassed by their own nominee.',
      'The base enjoys the defiance for a day. The larger story, unfortunately, is that the Democratic nominee is publicly fighting the most prominent surviving figure in his own party.'
    ]
  );
}

function k08InstallReassuranceQuestion(){
  const p=k08ReactiveProfile(), vp=p.vp||'gravel', vpName=k08VpLabel();
  const antiEstCost={napolitano:-1,feingold:-1,patrick:-1,lee:-2,gravel:-2,paul:-4}[vp] ?? -2;
  if(p.conspiracyCrisis){
    k08SetReactiveQuestion(19,
      `July 2008: The campaign has a problem bigger than another bad news cycle. Voter unease from the assassination has mixed with conspiracy talk around parts of the anti-establishment movement, and Republicans are now running clips meant to make the Kucinich-${vpName.split(' ').pop()} ticket look unstable. A network anchor asks what you actually believe happened to Barack Obama.`,
      [73,74,75,76],
      [
        'There is no evidence of a wider plot. Say that plainly, reject speculation from our own supporters, and promise that any credible new evidence will be handled by independent investigators.',
        'Use the moment to announce a broad national-unity governing team, including experienced Democrats who have never been part of our movement.',
        'Return to the independent commission idea. The way to kill conspiracy theories is to put every established fact in public view.',
        'Refuse the premise. The government has not earned blind trust, and people have every right to keep asking who benefited from Obama’s death.'
      ], [.044,.034,.014,-.035],
      [
        {conspiracyHeat:-3,voterAnxiety:-3,publicPerception:3,partySupport:2,nationalUnity:2},
        {voterAnxiety:-2,partySupport:3,publicPerception:2,progressiveTrust:-1},
        {conspiracyHeat:-1,voterAnxiety:-1,mediaRelationship:1,publicPerception:1},
        {conspiracyHeat:3,voterAnxiety:3,partySupport:-2,publicPerception:-3,progressiveTrust:2}
      ],
      [
        'This is the clean break nervous voters and party officials wanted. Some activists complain, but the campaign stops looking as radical as it could have.',
        'The personnel announcement reassures institutional Democrats and softens the “chaos” argument. It does not fully answer the conspiracy question, which keeps the story alive another few days.',
        'A commission sounds responsible, but at this stage it also tells voters there is still something unresolved. You lower the temperature without shutting down all debate',
        'This is exactly the clip Republicans wanted. The answer electrifies the most distrustful supporters and terrifies almost everyone else.'
      ]);
    return;
  }
  if(p.securityHigh){
    const vpFrame={
      napolitano:'Napolitano helps, but Republicans insist that border-state executive experience cannot substitute for a commander in chief they call naïve.',
      patrick:'Patrick’s calm style helps little on its own; Republicans are making the lack of national-security experience on both halves of the ticket the issue.',
      lee:'Lee’s anti-war record lets Republicans portray the ticket as ideologically opposed to the entire post-9/11 security establishment.',
      gravel:'Gravel’s rhetoric is being clipped into ads arguing that the ticket treats American security institutions with contempt.',
      paul:'The cross-party Paul choice has made the attack much sharper: Republicans say both men are united less by a governing program than by hostility to the national-security consensus.'
    }[vp];
    const hillaryMult={napolitano:.043,feingold:.036,patrick:.039,lee:.018,gravel:.008,paul:-.016}[vp] ?? .015;
    k08SetReactiveQuestion(19,
      `July 2008: ${vpFrame} Donors and Democratic governors are quietly asking for a concrete signal that a Kucinich administration would not hand foreign policy to the movement fringe. One suggestion keeps coming up: promise a mainstream national-security figure for Secretary of State.`,
      [73,74,75,76],
      [
        'Say it directly: I would be comfortable asking Hillary Clinton to serve as Secretary of State. No one could mistake that for an unserious foreign-policy team.',
        'Do not name Clinton. Announce that the transition team is vetting respected diplomats, generals and senators from across the Democratic coalition.',
        'My judgment is the reassurance. I opposed Iraq when most of Washington got it wrong, and I will build a professional team that implements that judgment.',
        'Reject the whole exercise. The national-security establishment gave us Iraq, torture and permanent war; I did not win this nomination to put it back in charge.'
      ], [hillaryMult,.031,.017,-.018],
      [
        {securityConcern:-3,partySupport:3,publicPerception:2,voterAnxiety:-2,progressiveTrust:antiEstCost},
        {securityConcern:-2,partySupport:2,publicPerception:2,voterAnxiety:-1,progressiveTrust:-1},
        {securityConcern:-1,publicPerception:1,progressiveTrust:1},
        {securityConcern:2,partySupport:-2,progressiveTrust:3,voterAnxiety:1}
      ],
      [
        vp==='paul' ? 'The reassurance works with nervous Democrats, but the coalition rupture is immediate. Paul allies openly ask why they crossed party lines only to help install Hillary Clinton at State; the net political effect is ugly.' : (vp==='gravel'||vp==='lee') ? 'Clinton’s name instantly reassures the party and much of the press. The price is visible on the anti-war wing of the ticket, where allies complain that the campaign is rebuilding the establishment it defeated.' : 'This is an unmistakable governing signal. Clinton does not accept a job on the spot, but she welcomes the confidence publicly, and the “too risky to govern” attack loses force.',
        'This is less dramatic and probably more sustainable. The press gets its reassurance story without forcing the campaign into a personnel commitment that could split the coalition.',
        'The answer is coherent and true to your strongest argument: judgment mattered more than credentials on Iraq. It helps, but voters who wanted names and structure are only partly reassured.',
        'The movement loves it. Everyone else hears confirmation that a Kucinich administration intends to wage war on the institutions it would need to govern through.'
      ]);
    return;
  }
  if(p.anxietyHigh){
    k08SetReactiveQuestion(19,
      `July 2008: The issue is no longer any single policy. Focus groups keep using the same words about the Kucinich-${vpName.split(' ').pop()} ticket: “interesting,” “honest,” and then “risky.” After a year of assassination, unrest and party collapse, voters want to know whether your administration would be stable on day one. How do you answer the readiness question?`,
      [73,74,75,76],
      [
        'Publish a transition council now: governors, senior members of Congress, economists and experienced foreign-policy hands. Make the government-in-waiting visible.',
        'Promise a cabinet drawn from every wing of the Democratic Party and say publicly that figures such as Hillary Clinton would be welcome to serve.',
        'Lean on the congressional record. I have spent more than a decade in Washington; unconventional politics does not mean unfamiliarity with government.',
        'Do not validate the fear campaign. The people who call us risky are the same people who gave the country Iraq and this economy.'
      ], [.038,.034,.019,-.010],
      [
        {voterAnxiety:-3,partySupport:2,publicPerception:3,securityConcern:-1,progressiveTrust:-1},
        {voterAnxiety:-2,partySupport:3,nationalUnity:2,progressiveTrust:-1},
        {voterAnxiety:-1,publicPerception:2},
        {voterAnxiety:1,partySupport:-1,progressiveTrust:2,publicPerception:-1}
      ],
      [
        'The photographs do almost as much work as the speech. For the first time, voters can picture actual people walking into departments on January 20 rather than an insurgent campaign somehow becoming a government.',
        'The breadth helps. Anti-establishment activists grumble, but nervous Democrats finally hear that victory would not mean a purge of everyone who lost the primary fight.',
        'It is a respectable answer and stops some of the caricature. It cannot entirely substitute for showing voters who would surround you.',
        'You win the argument with people who already agree. The voters asking whether you are risky hear another reason to keep asking.'
      ]);
    return;
  }
  if(p.partyWeak){
    k08SetReactiveQuestion(19,
      `July 2008: Democratic unity remains visibly incomplete. Several senators are skipping joint appearances, major donors are hedging, and the Clinton statement did not settle the question. With ${vpName} on the ticket, what do you do about a party establishment that still does not quite believe in you?`,
      [73,74,75,76],
      [
        'Offer an explicit unity compact: shared fundraising, a broad cabinet, and regular consultation with congressional Democrats.',
        'Ask Clinton, labor leaders and Democratic governors to appear together and make the election about defeating the Republican ticket, not relitigating the primary.',
        'Go around Washington. Build the campaign through unions, local parties and small donors until reluctant leaders have no choice but to follow.',
        'Make the split public. If elected Democrats cannot support the Democratic nominee, voters deserve to know whose side they are on.'
      ], [.036,.033,.021,-.017],
      [
        {partySupport:4,nationalUnity:2,publicPerception:2,progressiveTrust:-1},
        {partySupport:3,nationalUnity:3,voterAnxiety:-1},
        {partySupport:1,progressiveTrust:2,publicPerception:1},
        {partySupport:-3,progressiveTrust:3,nationalUnity:-2,voterAnxiety:1}
      ],
      ['The compact is not romantic, but it works. Members who were keeping their distance now have something concrete to point to when explaining why they are campaigning for you.','A unity tableau does not erase ideology, but it changes the visual story from civil war to coalition.','This strengthens the campaign from below and keeps your independence intact. It is slower than the institutional fix the party wanted.','The confrontation thrills supporters and confirms every fear among Democrats who were already searching for an excuse to stay away.']);
    return;
  }
  if(p.progressiveOpportunity){
    k08SetReactiveQuestion(19,
      `July 2008: Something unexpected is happening. Your favorability has improved while the campaign’s progressive base has stayed engaged, and organizers report unusual enthusiasm among young voters, union activists and anti-war independents. For once, we are being offered an opportunity rather than a crisis. How do we use it?`,
      [73,74,75,76],
      [
        'Turn the campaign into a governing coalition: peace, universal health care, labor rights and constitutional reform, all presented as one practical mandate.',
        'Launch a massive registration and volunteer drive in industrial states and college towns. If the electorate changes, the map changes.',
        'Use the opening to reassure moderates. The movement is secure; now prove we can govern for people who did not vote for us.',
        'Go maximalist. If the country is finally listening, put every structural reform we believe in on the table at once.'
      ], [.043,.039,.031,.010],
      [
        {progressiveTrust:2,publicPerception:2,nationalUnity:1},
        {progressiveTrust:2,publicPerception:1},
        {publicPerception:3,voterAnxiety:-1,partySupport:1},
        {progressiveTrust:3,voterAnxiety:1,publicPerception:-1}
      ],
      ['This is the campaign at its best: ideological without sounding sectarian. Reporters begin asking what a Kucinich mandate would mean rather than whether one is possible.','The organizing surge is real and gives the ticket a path through states that looked dead months ago.','The pivot reassures soft voters without provoking the base because you earned enough trust first. This is exactly the kind of positive combination the campaign could not attempt earlier.','The activists are ecstatic. The press spends the next week choosing the least popular proposal in the package and asking every Democrat in America whether they support it.']);
    return;
  }
  k08SetReactiveQuestion(19,
    `July 2008: With the ticket finally set, the press is trying to decide whether Dennis Kucinich can be imagined as a president rather than a protest candidate. ${vpName} changes that picture, but not by itself. What is the best way to introduce the governing argument?`,
    [73,74,75,76],
    ['Publish a disciplined first-hundred-days agenda and surround it with credible people who could actually carry it out.','Make judgment the argument: Iraq, civil liberties and corporate power all show that the conventional wisdom has failed more often than we have.','Keep the campaign movement-driven. The more we imitate a normal ticket, the easier it is to forget why we are here.','Treat the entire “ready to govern” question as establishment gatekeeping and attack the premise.'],
    [.032,.028,.017,-.010],
    [{publicPerception:3,partySupport:2,voterAnxiety:-1},{publicPerception:2,progressiveTrust:1},{progressiveTrust:2,publicPerception:1},{progressiveTrust:2,partySupport:-1,voterAnxiety:1}],
    ['This is conventional in the useful sense. The campaign looks less like an improbable nomination and more like a possible administration.','Your record remains one of the strongest assets available. The argument persuades voters who value being right before being fashionable.','The base responds, but the readiness question survives.','The answer satisfies activists who resent the premise and hardens the doubts of nearly everyone who asked it sincerely.']);
}

function k08InstallLateReactiveQuestion(){
  const p=k08ReactiveProfile(), vp=p.vp||'gravel', vpName=k08VpLabel();
  if(p.conspiracyCrisis){
    k08SetReactiveQuestion(28,
      `October 2008: In the final debate, the moderator abandons the prepared domestic-policy format and asks the question your campaign has dreaded: “Do you and ${vpName} believe Barack Obama was the victim of a conspiracy, and can the country trust you to separate evidence from suspicion in the Oval Office?”`,
      [109,110,111,112],
      ['No. There is no evidence of a wider conspiracy, and a president has a duty to distinguish unanswered questions from unsupported claims.','Say the existing record is clear, then promise that any genuinely new evidence will go to independent investigators rather than political appointees.','Pivot: the real lesson of this year is that secrecy destroys trust, which is why the administration will strengthen transparency and congressional oversight.','Say you will not tell Americans what conclusions they are permitted to draw. The government should open every file and let the public decide.'],
      [.048,.039,.026,-.040],
      [{conspiracyHeat:-4,voterAnxiety:-4,publicPerception:4,partySupport:2},{conspiracyHeat:-2,voterAnxiety:-2,publicPerception:3},{conspiracyHeat:-1,publicPerception:2,progressiveTrust:1},{conspiracyHeat:3,voterAnxiety:4,publicPerception:-4,partySupport:-3,progressiveTrust:2}],
      ['It is painful to some supporters, but devastatingly effective with everyone else. The Republican campaign loses its easiest closing argument in a single answer.','This lands as cautious and institutional. It does not fully kill the story, but it substantially lowers the temperature.','A good constitutional answer that avoids validating the theory. The moderator moves on.','The hall goes silent. By morning, the election is again a referendum on whether the Democratic ticket is too unstable to trust.']);
    return;
  }
  if(p.securityHigh){
    k08SetReactiveQuestion(28,
      `October 2008: The final debate turns unexpectedly toward terrorism and the Russia-Georgia war. Your opponent says the financial crisis does not make the world safer and argues that a Kucinich-${vpName.split(' ').pop()} administration would invite adversaries to test the United States. How do you answer the closing national-security attack?`,
      [109,110,111,112],
      ['Draw a hard distinction between restraint and passivity: defend allies, pursue terrorists through lawful intelligence and policing, and require Congress before elective wars.','Point to the experienced foreign-policy team you have assembled and make the answer about competence rather than ideology.','Return to Iraq: the people lecturing us about toughness made the gravest strategic mistake of this generation. Judgment is national security.','Reject the frame entirely. American militarism has created more danger than it prevented, and the next administration should dismantle the architecture of permanent war.'],
      [.041,.037,.030,-.021],
      [{securityConcern:-3,voterAnxiety:-2,publicPerception:3},{securityConcern:-3,partySupport:2,publicPerception:2},{securityConcern:-2,progressiveTrust:1,publicPerception:2},{securityConcern:2,progressiveTrust:3,partySupport:-2,voterAnxiety:1}],
      ['This is the answer Republicans hoped you could not give: restrained, constitutional and recognizably presidential without surrendering the anti-war case.','The names and structure matter. Voters who worried about the ticket can now imagine a conventional national-security process around an unconventional president.','Iraq remains powerful evidence for your judgment. The answer works especially well with voters exhausted by Republican claims to a monopoly on toughness.','The anti-war base cheers. Swing voters hear a promise to conduct an experiment with national security at the exact moment Republicans told them to fear one.']);
    return;
  }
  if(p.anxietyHigh || p.partyWeak){
    k08SetReactiveQuestion(28,
      `October 2008: The economy has made this a real race, but the final debate audience still has one unresolved concern: whether the Kucinich-${vpName.split(' ').pop()} coalition would produce a stable administration or a permanent fight with Washington. You get ninety seconds to answer.`,
      [109,110,111,112],
      ['Name the governing structure: bipartisan emergency economic council, experienced cabinet, weekly meetings with congressional leaders and a disciplined first-year agenda.','Say that coalition government is a strength. The cabinet will include progressives, mainstream Democrats and qualified independents who agree on the program even when they disagree on ideology.','Make the crisis itself the answer: the supposedly stable establishment delivered war and financial collapse; different judgment is not instability.','Promise to take on both parties when necessary. Washington is afraid of disruption because too many people profit from the status quo.'],
      [.043,.038,.031,.006],
      [{voterAnxiety:-3,partySupport:3,publicPerception:3},{voterAnxiety:-2,partySupport:2,nationalUnity:2},{voterAnxiety:-1,publicPerception:2,progressiveTrust:1},{voterAnxiety:1,partySupport:-2,progressiveTrust:2}],
      ['This is concrete enough to be reassuring rather than merely rhetorical. The “chaos” attack gets harder to sustain.','The coalition argument fits the ticket and broadens it at the same time.','A strong counterpunch, though it answers the governing-process question only indirectly.','The line excites the base and restores the very uncertainty the campaign had spent weeks trying to reduce.']);
    return;
  }
  if(p.progressiveOpportunity){
    k08SetReactiveQuestion(28,
      `October 2008: The financial collapse has changed the race so completely that the final debate moderator asks what a Kucinich victory would actually be a mandate to do. The question is an opportunity: the campaign is no longer being asked only whether it can survive. How large a mandate do you claim?`,
      [109,110,111,112],
      ['A focused one: universal health care, homeowner relief, financial reform, labor rights and an end to the Iraq War. Win authority for a program people can recognize.','A democratic transformation. Tie peace, economic democracy and constitutional reform together and say the old consensus has exhausted itself.','Keep the mandate deliberately broad: competent recovery, clean government and a foreign policy of restraint. Let Congress fight over the details after the election.','Use the moment to revive every major proposal of the primary campaign. If voters want change, give them the full meaning of the word.'],
      [.046,.041,.034,.012],
      [{progressiveTrust:2,publicPerception:3,nationalUnity:1},{progressiveTrust:3,publicPerception:2},{publicPerception:3,partySupport:2,voterAnxiety:-1},{progressiveTrust:3,voterAnxiety:1,publicPerception:-1}],
      ['The agenda sounds ambitious because the moment is ambitious, but it is short enough to look governable.','This is the sweeping version of the Kucinich argument, and in this campaign state voters are finally willing to hear it.','A cautious but effective close for persuadable voters. Some activists wanted more, but few feel betrayed.','You turn a gift into a catalogue. Supporters love the ambition; undecided voters start wondering which controversial item would actually come first.']);
    return;
  }
  k08SetReactiveQuestion(28,
    `October 2008: The final debate will focus on domestic policy. The financial crisis has erased much of the old campaign, but voters still want to know what fundamental choice they are making between you and ${({romney:"Romney",mccain:"McCain",giuliani:"Giuliani",perry:"Perry",forbes:"Forbes"})[String(campaignTrail_temp.k08?.republicanNominee||"").toLowerCase()]||"the Republican nominee"}. What should be the closing contrast?`,
    [109,110,111,112],
    ['Make health care the closing contrast.','Make wages, jobs and the recovery the closing contrast.','Make competence, clean government and a disciplined transition the closing contrast.','Tie the whole election together: war abroad and concentrated power at home came from the same politics.'],
    [.026,.035,.031,.022],
    [{publicPerception:1},{publicPerception:2,partySupport:1},{publicPerception:2,voterAnxiety:-1,partySupport:1},{progressiveTrust:2,publicPerception:1}],
    ['This is familiar ground and gives voters a concrete reason to choose you.','This meets the electorate where it is. The crisis makes an economic closing argument especially potent.','The competence message helps voters who came to you late and still worry about the transition from insurgency to government.','The argument is intellectually coherent and fires up the movement, though it asks voters to absorb a lot in a closing answer.']);
}

