(function(){
  function shorten(s){
    if(typeof s!=='string' || s.length<=300) return s;
    const sentences=s.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[s];
    let out='';
    for(const part of sentences){
      if((out+part).trim().length>275) break;
      out+=part;
    }
    return out.trim() || s.slice(0,272).trim()+'...';
  }
  for(const a of (campaignTrail_temp.answers_json||[])){
    if(a?.fields?.feedback) a.fields.feedback=shorten(a.fields.feedback);
  }
  for(const f of (campaignTrail_temp.answer_feedback_json||[])){
    if(f?.fields?.answer_feedback) f.fields.answer_feedback=shorten(f.fields.answer_feedback);
  }
})();

